package com.quincaisoft.integrations.infrastructure;
import com.quincaisoft.integrations.api.CollectionProvider;
import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;import tools.jackson.databind.json.JsonMapper;
/** Pure provider transport: caller must persist reference and request before network, and reconcile verified result transactionally. */
public final class MtnCollectionAdapter implements CollectionProvider {
 public record Configuration(URI origin,String environment,String userId,String credential,String subscriptionKey,boolean liveEnabled) {
  public Configuration {if(origin==null||!"https".equals(origin.getScheme())||origin.getPort()!=-1||origin.getUserInfo()!=null||origin.getQuery()!=null||origin.getFragment()!=null||!Set.of("sandbox.momodeveloper.mtn.com","proxy.momoapi.mtn.com","ericssonbasicapi1.azure-api.net","momoapi.momo.africa").contains(origin.getHost())||!(origin.getPath().isEmpty()||origin.getPath().equals("/")))throw new IllegalArgumentException("Approved MTN HTTPS origin required");if(!Set.of("sandbox","mtncameroon").contains(environment))throw new IllegalArgumentException("Explicit supported environment required");if(environment.equals("sandbox")!=origin.getHost().equals("sandbox.momodeveloper.mtn.com"))throw new IllegalArgumentException("Origin/environment mismatch");for(var s:List.of(userId,credential,subscriptionKey))if(s.isBlank())throw new IllegalArgumentException("Merchant credentials required");}
  @Override public String toString(){return "MTN["+origin+","+environment+",credentials=REDACTED]";}
 }
 public record Response(int status,String body){}
 @FunctionalInterface public interface Transport {Response send(String method,URI uri,Map<String,String>headers,String body)throws Exception;}
 public static Transport httpTransport(){var client=HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).connectTimeout(Duration.ofSeconds(10)).build();return (method,uri,headers,body)->{var r=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(20)).method(method,body.isEmpty()?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body));headers.forEach(r::header);var response=client.send(r.build(),HttpResponse.BodyHandlers.ofString());if(response.body().length()>100000)throw new IllegalStateException("Oversize provider response");return new Response(response.statusCode(),response.body());};}
 private final Configuration config;private final Transport transport;private final JsonMapper json=JsonMapper.builder().build();
 public MtnCollectionAdapter(Configuration config,Transport transport){this.config=config;this.transport=transport;}
 private void validate(Intent i){if(i==null||i.reference()==null||i.externalId()==null||i.externalId().isBlank()||i.externalId().length()>100||i.phone()==null||!i.phone().matches("[0-9]{9,15}")||i.amount()==null||!i.amount().matches("[1-9][0-9]*"))throw new IllegalArgumentException("Valid immutable intent required");Long.parseLong(i.amount());if(!i.currency().equals(config.environment().equals("sandbox")?"EUR":"XAF"))throw new IllegalArgumentException("Sandbox EUR and production XAF must never mix");if(!config.environment().equals("sandbox")&&!i.phone().matches("2376[0-9]{8}"))throw new IllegalArgumentException("Cameroon mobile number required");if(!config.environment().equals("sandbox")&&!config.liveEnabled())throw new IllegalStateException("Live provider calls disabled");}
 private Map<String,String> headers(String auth){return Map.of("Authorization",auth,"Ocp-Apim-Subscription-Key",config.subscriptionKey(),"X-Target-Environment",config.environment(),"Content-Type","application/json");}
 private String token()throws Exception {String basic=Base64.getEncoder().encodeToString((config.userId()+":"+config.credential()).getBytes(StandardCharsets.UTF_8));var r=transport.send("POST",config.origin().resolve("/collection/token"),headers("Basic "+basic),"");if(r.status()!=200)throw new IllegalStateException("Provider authentication unavailable");String token=json.readTree(r.body()).path("access_token").asString();if(token.isBlank())throw new IllegalStateException("Provider token unavailable");return token;}
 public Result initiate(Intent intent){validate(intent);try{var headers=new HashMap<>(headers("Bearer "+token()));headers.put("X-Reference-Id",intent.reference().toString());var body=json.writeValueAsString(Map.of("amount",intent.amount(),"currency",intent.currency(),"externalId",intent.externalId(),"payer",Map.of("partyIdType","MSISDN","partyId",intent.phone()),"payerMessage","QuincaiSoft payment","payeeNote","Merchant collection"));var r=transport.send("POST",config.origin().resolve("/collection/v1_0/requesttopay"),headers,body);if(r.status()==202)return new Result(Outcome.PENDING,null);if(r.status()==409)return query(intent);return new Result((r.status()>=500||r.status()==408||r.status()==429)?Outcome.UNKNOWN:Outcome.FAILED,null);}catch(Exception e){return new Result(Outcome.UNKNOWN,null);}}
 public Result query(Intent intent){validate(intent);try{var r=transport.send("GET",config.origin().resolve("/collection/v1_0/requesttopay/"+intent.reference()),headers("Bearer "+token()),"");if(r.status()!=200)return new Result(Outcome.UNKNOWN,null);var d=json.readTree(r.body());String status=d.path("status").asString();if(status.equals("FAILED"))return new Result(Outcome.FAILED,null);if(status.equals("PENDING"))return new Result(Outcome.PENDING,null);if(!status.equals("SUCCESSFUL"))return new Result(Outcome.UNKNOWN,null);String transaction=d.path("financialTransactionId").asString();if(new java.math.BigDecimal(intent.amount()).compareTo(new java.math.BigDecimal(d.path("amount").asString()))!=0||!intent.currency().equals(d.path("currency").asString())||!intent.externalId().equals(d.path("externalId").asString())||!intent.phone().equals(d.path("payer").path("partyId").asString())||!"MSISDN".equals(d.path("payer").path("partyIdType").asString())||transaction.isBlank())return new Result(Outcome.UNKNOWN,null);return new Result(config.environment().equals("sandbox")?Outcome.SANDBOX_VERIFIED:Outcome.VERIFIED,transaction);}catch(Exception e){return new Result(Outcome.UNKNOWN,null);}}
}
